SELECT region, CASE WHEN sqft >= 18035 THEN 'HIGH' ELSE 'LOW' END AS sqft_tier, SIZE(COLLECT_SET(city)) AS num_cities, SORT_ARRAY(COLLECT_SET(region)) AS region_list, ROUND(SUM(sqft) / NULLIF(COUNT(CASE WHEN region = 'South' THEN 1 END), 0), 2) AS sqft_per_south, SIZE(COLLECT_SET(region)) AS num_regions, BIT_AND(sqft) AS sqft_bit_and, MIN(sqft) AS min_sqft, DENSE_RANK() OVER (PARTITION BY region ORDER BY SIZE(COLLECT_SET(city)) DESC) AS num_cities_dense_rank FROM stores GROUP BY region, sqft_tier;
